sql_skeleton:
SELECT
    MIN({measure_col}) AS min_value,
    MAX({measure_col}) AS max_value,
    MAX({measure_col}) - MIN({measure_col}) AS range_width
FROM {table}
WHERE {measure_col} IS NOT NULL;

WITH grouped AS (
    SELECT {group_col} AS value_label, COUNT(*) AS support
    FROM {table}
    GROUP BY {group_col}
), ranked AS (
    SELECT
        value_label,
        support,
        CAST(support AS FLOAT) / NULLIF(SUM(support) OVER (), 0) AS support_share,
        SUM(support) OVER (ORDER BY support DESC, value_label ROWS UNBOUNDED PRECEDING) AS cumulative_support
    FROM grouped
)
SELECT *
FROM ranked
ORDER BY support DESC, value_label;

SELECT
    {key_col},
    COUNT(*) AS support,
    AVG({measure_col}) AS avg_response
FROM {table}
GROUP BY {key_col}
HAVING COUNT(*) >= {min_support}
ORDER BY support DESC, avg_response DESC;

WITH grouped AS (
    SELECT {group_col} AS value_label, COUNT(*) AS support
    FROM {table}
    GROUP BY {group_col}
)
SELECT
    value_label,
    support,
    CAST(support AS FLOAT) / NULLIF(SUM(support) OVER (), 0) AS support_share,
    ROW_NUMBER() OVER (ORDER BY support DESC, value_label) AS support_rank
FROM grouped
ORDER BY support DESC, value_label;

SELECT {group_col}, {group_col_2}, COUNT(*) AS row_count
FROM {table}
WHERE {predicate_col} {predicate_op} {predicate_value}
GROUP BY {group_col}, {group_col_2}
ORDER BY row_count DESC;

SELECT {group_col}, {group_col_2},
       AVG(CASE WHEN {target_col} = {target_value} THEN 1 ELSE 0 END) AS target_rate
FROM {table}
GROUP BY {group_col}, {group_col_2}
ORDER BY target_rate DESC;

SELECT {group_col},
       PERCENTILE_CONT({percentile_value}) WITHIN GROUP (ORDER BY {measure_col})
           FILTER (WHERE {condition_col} = {condition_value}) AS conditional_percentile
FROM {table}
GROUP BY {group_col}
ORDER BY conditional_percentile DESC;

SELECT {group_col},
       AVG(CASE WHEN {condition_col} = {condition_value} THEN 1 ELSE 0 END) AS condition_rate
FROM {table}
GROUP BY {group_col}
ORDER BY condition_rate DESC;

SELECT {group_col}, STDDEV({measure_col}) AS measure_stddev
FROM {table}
GROUP BY {group_col}
ORDER BY measure_stddev DESC
LIMIT {top_k};

WITH grouped AS (
    SELECT {group_col},
           SUM(CASE WHEN {condition_col} = {positive_value} THEN 1 ELSE 0 END) AS numerator_count,
           SUM(CASE WHEN {condition_col} = {negative_value} THEN 1 ELSE 0 END) AS denominator_count
    FROM {table}
    GROUP BY {group_col}
)
SELECT {group_col},
       CAST(numerator_count AS FLOAT) / NULLIF(denominator_count, 0) AS condition_ratio
FROM grouped
ORDER BY condition_ratio DESC;

WITH ranked AS (
    SELECT {measure_col},
           ROW_NUMBER() OVER (ORDER BY {measure_col}) AS row_num,
           COUNT(*) OVER () AS total_rows
    FROM {table}
    WHERE {predicate_col} {predicate_op} {predicate_value}
)
SELECT AVG({measure_col}) AS median_measure
FROM ranked
WHERE row_num BETWEEN (total_rows + 1) / 2 AND (total_rows + 2) / 2;

SELECT DISTINCT {group_col},
       AVG({measure_col}) OVER (PARTITION BY {group_col}) AS avg_measure
FROM {table}
ORDER BY avg_measure DESC;

SELECT DATE_TRUNC('{time_grain}', {time_col}) AS time_bucket,
       COUNT(*) AS event_count
FROM {table}
WHERE {predicate_col} {predicate_op} {predicate_value}
GROUP BY time_bucket
ORDER BY time_bucket;

WITH bucketed AS (
    SELECT DATE_TRUNC('{time_grain}', {time_col}) AS time_bucket,
           {group_col},
           COUNT(*) AS event_count
    FROM {table}
    WHERE {predicate_col} {predicate_op} {predicate_value}
    GROUP BY time_bucket, {group_col}
)
SELECT time_bucket,
       {group_col},
       event_count,
       AVG(event_count) OVER (
           PARTITION BY {group_col}
           ORDER BY time_bucket
           ROWS BETWEEN {lookback_rows} PRECEDING AND CURRENT ROW
       ) AS moving_avg_count
FROM bucketed
ORDER BY {group_col}, time_bucket;

WITH period_counts AS (
    SELECT {group_col},
           SUM(CASE WHEN {time_col} >= {current_period_start} AND {time_col} < {current_period_end} THEN 1 ELSE 0 END) AS current_count,
           SUM(CASE WHEN {time_col} >= {previous_period_start} AND {time_col} < {previous_period_end} THEN 1 ELSE 0 END) AS previous_count
    FROM {table}
    GROUP BY {group_col}
)
SELECT {group_col}, current_count, previous_count,
       CAST(current_count AS FLOAT) / NULLIF(previous_count, 0) AS drift_ratio
FROM period_counts
WHERE CAST(current_count AS FLOAT) / NULLIF(previous_count, 0) < {drift_ratio_threshold}
ORDER BY drift_ratio ASC;

WITH item_stats AS (
    SELECT {group_col}, {item_col}, AVG({measure_col}) AS avg_measure
    FROM {table}
    GROUP BY {group_col}, {item_col}
), group_baseline AS (
    SELECT {group_col}, AVG(avg_measure) AS group_avg
    FROM item_stats
    GROUP BY {group_col}
), eligible AS (
    SELECT i.{group_col}, i.{item_col}, i.avg_measure
    FROM item_stats AS i
    JOIN group_baseline AS g
      ON i.{group_col} = g.{group_col}
    WHERE i.avg_measure > g.group_avg * {baseline_fraction}
)
SELECT {group_col}, {item_col}, avg_measure,
       RANK() OVER (PARTITION BY {group_col} ORDER BY avg_measure DESC) AS within_group_rank
FROM eligible
ORDER BY avg_measure DESC
LIMIT {top_k};

SELECT {group_col}, {item_col},
       SUM({measure_col}) AS total_measure,
       SUM({measure_col}) * 100.0 / SUM(SUM({measure_col})) OVER (PARTITION BY {group_col}) AS share_within_group
FROM {table}
GROUP BY {group_col}, {item_col}
ORDER BY share_within_group DESC;

SELECT SUM({measure_col}) AS total_measure
FROM {table}
WHERE {band_col} BETWEEN {lower_bound} AND {upper_bound};

SELECT
    {group_col},
    COUNT(*) AS total_rows,
    SUM(CASE WHEN {missing_col} IS NULL THEN 1 ELSE 0 END) AS missing_rows,
    AVG(CASE WHEN {missing_col} IS NULL THEN 1.0 ELSE 0.0 END) AS missing_rate
FROM {table}
GROUP BY {group_col}
ORDER BY missing_rate DESC, total_rows DESC;

SELECT
    {target_col},
    COUNT(*) AS total_rows,
    SUM(CASE WHEN {missing_col} IS NULL THEN 1 ELSE 0 END) AS missing_rows,
    AVG(CASE WHEN {missing_col} IS NULL THEN 1.0 ELSE 0.0 END) AS missing_rate
FROM {table}
GROUP BY {target_col}
ORDER BY missing_rate DESC, total_rows DESC;

SELECT {group_col}, COUNT(DISTINCT {entity_col}) AS distinct_entities
FROM {table}
WHERE {predicate_col} {predicate_op} {predicate_value}
GROUP BY {group_col}
ORDER BY distinct_entities DESC
LIMIT {top_k};

SELECT {group_col}, COUNT(*) AS support
FROM {table}
WHERE {predicate_col} {predicate_op} {predicate_value}
GROUP BY {group_col}
ORDER BY support DESC
LIMIT {top_k};

SELECT {group_col}, COUNT(*) AS row_count
FROM {table}
GROUP BY {group_col}
ORDER BY row_count DESC;

SELECT {group_col}, COUNT(DISTINCT {entity_col}) AS distinct_entities
FROM {table}
GROUP BY {group_col}
ORDER BY distinct_entities DESC
LIMIT {top_k};

SELECT {group_col},
       COUNT(*) AS support,
       AVG({measure_col}) AS avg_measure,
       COUNT(DISTINCT {entity_col}) AS distinct_entities
FROM {table}
GROUP BY {group_col}
ORDER BY support DESC
LIMIT {top_k};

SELECT {group_col}, {group_col_2}, COUNT(*) AS support
FROM {table}
GROUP BY {group_col}, {group_col_2}
ORDER BY support DESC
LIMIT {top_k};

SELECT {group_col}, SUM({measure_col}) AS total_measure
FROM {table}
GROUP BY {group_col}
ORDER BY total_measure DESC;

SELECT {group_col}, {group_col_2}, SUM({measure_col}) AS total_measure
FROM {table}
GROUP BY {group_col}, {group_col_2}
ORDER BY total_measure DESC;

SELECT {group_col}, {group_col_2},
       PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY {measure_col}) AS median_measure,
       STDDEV({measure_col}) AS measure_stddev
FROM {table}
GROUP BY {group_col}, {group_col_2}
ORDER BY median_measure DESC;

SELECT {group_col}, AVG({measure_col}) AS avg_measure
FROM {table}
GROUP BY {group_col}
ORDER BY avg_measure DESC;

SELECT {group_col}, AVG({measure_col}) AS avg_measure, COUNT(*) AS support
FROM {table}
GROUP BY {group_col}
HAVING COUNT(*) > {min_group_size}
ORDER BY {group_col};

SELECT {group_col}, {group_col_2}, AVG({measure_col}) AS avg_measure
FROM {table}
GROUP BY {group_col}, {group_col_2}
ORDER BY avg_measure DESC;

SELECT {group_col},
       SUM({measure_col}) AS weighted_total,
       COUNT(*) AS support
FROM {table}
GROUP BY {group_col}
HAVING COUNT(*) >= {min_support}
ORDER BY weighted_total DESC
LIMIT {top_k};

SELECT {group_col}, SUM({measure_col}) AS total_measure
FROM {table}
WHERE {predicate_col} {predicate_op} {predicate_value}
GROUP BY {group_col}
ORDER BY total_measure DESC
LIMIT {top_k};

WITH grouped AS (
    SELECT {group_col}, SUM({measure_col}) AS total_measure
    FROM {table}
    GROUP BY {group_col}
)
SELECT {group_col}, total_measure
FROM grouped
WHERE total_measure = (SELECT MAX(total_measure) FROM grouped)
ORDER BY {group_col};

SELECT {group_col}, {group_col_2},
       SUM({measure_col}) AS sum_measure,
       AVG({measure_col}) AS avg_measure,
       COUNT(*) AS support
FROM {table}
WHERE {predicate_col} {predicate_op} {predicate_value}
GROUP BY {group_col}, {group_col_2}
ORDER BY {group_col}, {group_col_2};

SELECT {group_col},
       PERCENTILE_CONT({percentile_value}) WITHIN GROUP (ORDER BY {measure_col}) AS percentile_measure
FROM {table}
GROUP BY {group_col}
ORDER BY percentile_measure DESC;

WITH ranked AS (
    SELECT
        {group_col} AS group_value,
        {measure_col} AS measure_value,
        ROW_NUMBER() OVER (PARTITION BY {group_col} ORDER BY {measure_col} DESC) AS measure_rank
    FROM {table}
    WHERE {measure_col} IS NOT NULL
)
SELECT group_value, measure_value, measure_rank
FROM ranked
WHERE measure_rank <= {top_n}
ORDER BY group_value, measure_rank;

SELECT
    {group_col},
    COUNT(*) AS support
FROM {table}
GROUP BY {group_col}
ORDER BY support ASC, {group_col}
LIMIT {top_k};

SELECT
    {group_col},
    {group_col_2},
    COUNT(*) AS support
FROM {table}
GROUP BY {group_col}, {group_col_2}
ORDER BY support ASC, {group_col}, {group_col_2}
LIMIT {top_k};

SELECT
    {group_col},
    COUNT(*) AS support,
    AVG(CASE WHEN {target_col} = {target_value} THEN 1 ELSE 0 END) AS focus_rate
FROM {table}
GROUP BY {group_col}
HAVING COUNT(*) >= {min_support}
ORDER BY focus_rate DESC, support ASC
LIMIT {top_k};

WITH entity_totals AS (
    SELECT {group_col}, {item_col}, SUM({measure_col}) AS entity_measure
    FROM {table}
    GROUP BY {group_col}, {item_col}
), subgroup_baseline AS (
    SELECT {group_col}, AVG(entity_measure) AS subgroup_avg
    FROM entity_totals
    GROUP BY {group_col}
)
SELECT e.{group_col}, e.{item_col}, e.entity_measure, b.subgroup_avg
FROM entity_totals AS e
JOIN subgroup_baseline AS b
  ON e.{group_col} = b.{group_col}
WHERE e.entity_measure > b.subgroup_avg * {baseline_multiplier}
ORDER BY e.entity_measure DESC;

WITH grouped AS (
    SELECT {group_col}, SUM({measure_col}) AS group_value
    FROM {table}
    GROUP BY {group_col}
), total AS (
    SELECT SUM(group_value) AS total_value
    FROM grouped
)
SELECT g.{group_col}, g.group_value
FROM grouped AS g
CROSS JOIN total AS t
WHERE g.group_value > t.total_value * {fraction_threshold}
ORDER BY g.group_value DESC;

SELECT {group_col}, SUM({measure_col}) AS total_measure
FROM {table}
GROUP BY {group_col}
HAVING SUM({measure_col}) > {measure_threshold}
ORDER BY total_measure DESC
LIMIT {top_k};
